#include <string.h>
int count_word(const char *text, const char *w) {
    char buf[1024];
    int c = 0;
    strncpy(buf, text, sizeof buf - 1);
    buf[sizeof buf - 1] = '\0';
    for (char *t = strtok(buf, " \t\n"); t; t = strtok(NULL, " \t\n")) {
