solution_c:
typedef struct { long long balance; } Account;
/* 0 on success, -1 on insufficient funds */
int withdraw(Account *a, long long amount) {
    if (amount > a->balance) return -1;
    a->balance -= amount;
    return 0;
}
/* 0 on success, -1 if amount is not positive */
int deposit(Account *a, long long amount) {
    if (amount <= 0) return -1;
    a->balance += amount;
    return 0;
}

