solution_python:
def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

solution_c:
/* Brute force O(n^2). An O(n) C version needs a hash table, which is
   usually too much for a relay turn. Returns 1 and fills out[] if found. */
int two_sum(const int a[], int n, int target, int out[2]) {
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++)
            if (a[i] + a[j] == target) {
                out[0] = i; out[1] = j;
                return 1;
            }
    return 0;
}

