#include <string.h>
int is_balanced(const char *s) {
    char st[256];
    int top = 0;
    for (; *s; s++) {
        char c = *s;
        if (!strchr("()[]{} ", c) && c != '\0') return 0;
        if (c == '(' || c == '[' || c == '{') st[top++] = c;
        else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) return 0;
            char o = st[--top];
            if ((c == ')' && o != '(') || (c == ']' && o != '[') || (c == '}' && o != '{'))
                return 0;
        }
    }
    return top == 0;
}

