    char ops[256];
    int top = 0, k = 0;
    for (; *e; e++) {
        char c = *e;
        if (isdigit((unsigned char)c)) { out[k++] = c; out[k++] = ' '; }
        else if (c == '(') ops[top++] = c;
        else if (c == ')') {
            while (ops[top - 1] != '(') { out[k++] = ops[--top]; out[k++] = ' '; }
            top--;
        } else {
            while (top > 0 && ops[top - 1] != '(' && prec(ops[top - 1]) >= prec(c)) {
                out[k++] = ops[--top]; out[k++] = ' ';
            }
            ops[top++] = c;
        }
    }
    while (top > 0) { out[k++] = ops[--top]; out[k++] = ' '; }
    if (k > 0) k--;          /* drop the trailing space */
    out[k] = '\0';
}

