def calc(s):
    result, num, sign = 0, 0, 1
    stack = []
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch in '+-':
            result += sign * num
            num, sign = 0, (1 if ch == '+' else -1)
        elif ch == '(':
            stack.append((result, sign))
            result, sign = 0, 1
        elif ch == ')':
            result += sign * num
            num = 0
            prev_result, prev_sign = stack.pop()
            result = prev_result + prev_sign * result
    return result + sign * num

