    int sr[256], ss[256], top = 0;
    for (; *s; s++) {
        char c = *s;
        if (isdigit((unsigned char)c)) num = num * 10 + (c - '0');
        else if (c == '+' || c == '-') {
            result += sign * num;
            num = 0;
            sign = (c == '+') ? 1 : -1;
        } else if (c == '(') {
            sr[top] = result; ss[top] = sign; top++;
            result = 0; sign = 1;
        } else if (c == ')') {
            result += sign * num;
            num = 0;
            top--;
            result = sr[top] + ss[top] * result;
        }
    }
    return result + sign * num;
}

