    int dist[MAXR][MAXC], qr[MAXR * MAXC], qc[MAXR * MAXC], head = 0, tail = 0;
    if (g[0][0] || g[R - 1][C - 1]) return -1;
    memset(dist, -1, sizeof dist);
    dist[0][0] = 0;
    qr[tail] = 0; qc[tail] = 0; tail++;
    while (head < tail) {
        int r = qr[head], c = qc[head]; head++;
        if (r == R - 1 && c == C - 1) return dist[r][c];
        for (int dr = -1; dr <= 1; dr++)
            for (int dc = -1; dc <= 1; dc++) {
                int nr = r + dr, nc = c + dc;
                if ((dr || dc) && nr >= 0 && nr < R && nc >= 0 && nc < C &&
                    g[nr][nc] == 0 && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    qr[tail] = nr; qc[tail] = nc; tail++;
                }
            }
    }
    return -1;
}

