/* sorts a in place, then scans runs: O(n log n) */
int most_frequent(int a[], int n) {
    qsort(a, n, sizeof a[0], cmp);
    int best = a[0], best_cnt = 0;
    for (int i = 0; i < n;) {
        int j = i;
        while (j < n && a[j] == a[i]) j++;
        if (j - i > best_cnt) { best_cnt = j - i; best = a[i]; }
        i = j;
    }
    return best;
}

