#define R 4
#define C 4
static int memo[R][C];
static int dfs(int g[R][C], int r, int c) {
    if (memo[r][c]) return memo[r][c];
    int best = 1;
    int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    for (int k = 0; k < 4; k++) {
        int nr = r + dr[k], nc = c + dc[k];
        if (nr >= 0 && nr < R && nc >= 0 && nc < C && g[nr][nc] > g[r][c]) {
            int cand = 1 + dfs(g, nr, nc);
            if (cand > best) best = cand;
        }
    }
    return memo[r][c] = best;
}
int longest_increasing_path(int g[R][C]) {
    int best = 0;
    for (int r = 0; r < R; r++)
        for (int c = 0; c < C; c++) {
            int d = dfs(g, r, c);
            if (d > best) best = d;
        }
    return best;
}

