def num_decodings(s):
    if not s or s[0] == '0':
        return 0
    prev, cur = 1, 1                       # ways for empty prefix, first char
    for i in range(1, len(s)):
        nxt = 0
        if s[i] != '0':
            nxt += cur
        if 10 <= int(s[i - 1:i + 1]) <= 26:
            nxt += prev
        prev, cur = cur, nxt
    return cur

