long long num_decodings(const char *s) {
    int n = 0;
    while (s[n]) n++;
    if (n == 0 || s[0] == '0') return 0;
    long long prev = 1, cur = 1;
    for (int i = 1; i < n; i++) {
        long long nxt = 0;
        if (s[i] != '0') nxt += cur;
        int two = (s[i - 1] - '0') * 10 + (s[i] - '0');
        if (two >= 10 && two <= 26) nxt += prev;
        prev = cur;
        cur = nxt;
    }
    return cur;
}

