def unique_paths(grid):
    if not grid or grid[0][0] == 1:
        return 0
    R, C = len(grid), len(grid[0])
    dp = [0] * C
    dp[0] = 1
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 1:
                dp[c] = 0
            elif c > 0:
                dp[c] += dp[c - 1]
    return dp[C - 1]

